INSERT INTO courses(id, slug, title, language, level, description, duration_text, sort_order) VALUES
('c', 'c', 'C Foundations', 'C', 'Beginner', 'Build a clear mental model of variables, control flow, functions, arrays, and memory.', '2.5h', 1),
('cpp', 'cpp', 'C++ Essentials', 'C++', 'Beginner', 'Explore objects, standard library tools, and expressive ways to organize a C++ program.', '3h', 2);
INSERT INTO lessons(id, course_id, position, title, kind, duration_minutes, summary, body, example_code, explanation) VALUES
('c-start','c',1,'A first look at C','Getting oriented',10,'Find the entry point and read a tiny C program.','A C program begins in main. The include line makes standard input and output tools available.','#include <stdio.h>\n\nint main(void) {\n    printf("Hello, world!\\n");\n    return 0;\n}','Start by finding the entry point, then read each line from top to bottom.'),
('c-values','c',2,'Values, variables & types','Working with data',14,'Give values names and choose a type.','A variable gives a value a name. Its type tells C how to interpret and store that value.','int score = 12;\nfloat average = 8.5f;\nchar grade = ''A'';','Choose a type that matches the kind of information you need to represent.'),
('c-decisions','c',3,'Making a decision','Conditions',12,'Choose a path with a true or false condition.','A condition lets a program choose a path. The expression inside the parentheses evaluates to true or false.','if (score >= 10) {\n    puts("Ready");\n} else {\n    puts("Keep practicing");\n}','Try tracing the condition with one value above and one value below the threshold.'),
('c-functions','c',4,'Function fundamentals','Reusable logic',12,'Name a task and pass it the information it needs.','A function gives a useful task a name. Parameters carry information in; a return value can carry a result back.','int add(int a, int b) {\n    return a + b;\n}\n\nint total = add(3, 4);','The signature describes the result type and the information the function expects.'),
('c-loops','c',5,'Repeating with loops','Iteration',13,'Repeat a block while its condition remains true.','A loop repeats a block of work while its condition remains true. A for loop puts setup, condition, and update together.','for (int i = 0; i < 3; i++) {\n    printf("%d\\n", i);\n}','Trace the condition and update so the loop has a clear stopping point.'),
('c-arrays','c',6,'A collection of values','Arrays',15,'Store several same-type values under one name.','An array stores several values of the same type under one name. Its positions start at index zero.','int marks[3] = {8, 9, 10};\nprintf("%d\\n", marks[0]);','For an array of three items, the valid indexes are 0, 1, and 2.'),
('c-pointers','c',7,'Pointers, gently','Memory basics',18,'Distinguish an address from the value stored there.','A pointer holds an address. The address-of operator finds where a variable lives; dereferencing reads the value at that address.','int value = 7;\nint *address = &value;\nprintf("%d\\n", *address);','First distinguish the address (&value) from the value at that address (*address).'),
('c-strings','c',8,'Text and C strings','Character arrays',16,'See how C represents a sequence of characters.','In C, text is represented as a sequence of characters ending with a special null character.','char name[] = "Mira";\nprintf("Hello, %s\\n", name);','The null terminator marks the end of a string for standard C string functions.'),
('cpp-start','cpp',1,'A first look at C++','Getting oriented',10,'Use iostream and identify the C++ entry point.','C++ includes standard input and output stream tools from iostream. The main function is where execution begins.','#include <iostream>\n\nint main() {\n    std::cout << "Hello, world!\\n";\n}','The scope operator in std::cout identifies cout as part of the std namespace.'),
('cpp-types','cpp',2,'Types and auto','Working with data',13,'Use familiar types and let clear initializers guide auto.','C++ offers familiar built-in types and can infer a variable type with auto when its initializer makes the type clear.','int count = 4;\nauto next = count + 1;\nconst std::string name = "Mira";','Use const for values that should not change after initialization.'),
('cpp-conditions','cpp',3,'Decisions & repetition','Control flow',13,'Choose paths and repeat work with readable control flow.','A range-based for loop is a readable way to visit each item in a range.','for (int n : {2, 4, 6}) {\n    std::cout << n << ''\\n'';\n}','Use a range-based loop when you need each value and do not need to manage an index.'),
('cpp-functions','cpp',4,'Functions & parameters','Reusable logic',14,'Give a focused task a name and useful parameters.','Functions collect a task into one named place. Clear parameter names make the call site easier to understand.','int add(int left, int right) {\n    return left + right;\n}\n\nauto total = add(3, 4);','Keep a function focused so its name can describe the work it performs.'),
('cpp-strings','cpp',5,'Working with strings','Standard library',13,'Work with text as a standard library value.','The std::string type manages text as a value and makes common operations easier to express.','#include <string>\n\nstd::string name = "Mira";\nname += " Rao";','The standard library gives you tested building blocks for everyday tasks.'),
('cpp-vectors','cpp',6,'A flexible collection','Standard library',15,'Use a vector for a sequence that can grow.','A vector is a sequence that can grow as you add items. It keeps track of its size for you.','#include <vector>\n\nstd::vector<int> marks{8, 9, 10};\nmarks.push_back(11);','Choose vector for a general-purpose, resizable sequence of values.'),
('cpp-classes','cpp',7,'Objects & classes','Object thinking',18,'Group related data and operations into a class.','A class groups related data and operations. An object is a value created from that class.','class Counter {\npublic:\n    void increment() { ++value; }\n    int get() const { return value; }\nprivate:\n    int value = 0;\n};','Use the public interface to expose what a caller needs and keep implementation details private.'),
('cpp-constructors','cpp',8,'Creating useful objects','Initialization',16,'Give an object a meaningful state at creation.','Initialization gives an object a meaningful state at the moment it is created.','struct Point {\n    double x;\n    double y;\n};\n\nPoint origin{0.0, 0.0};','Brace initialization makes the values used to create this Point visible at a glance.'),
('cpp-references','cpp',9,'References & const','Function design',16,'Read an existing object without copying or changing it.','A const reference can let a function read an existing object without making a copy or changing it.','void show(const std::string& text) {\n    std::cout << text;\n}','The ampersand in a parameter declaration means reference; const communicates read-only intent.'),
('cpp-algorithms','cpp',10,'Useful standard algorithms','Standard library',19,'Let a familiar algorithm express the operation.','The standard library includes algorithms that work with ranges, so you can focus on what you want to do.','#include <algorithm>\n\nstd::sort(values.begin(), values.end());','Prefer a well-known library algorithm when it clearly expresses the operation you need.');
