INSERT INTO questions(id, quiz_id, position, prompt, choices_json, correct_index, explanation) VALUES
('daily-1','daily',1,'What is 15% of 240?','["24","30","36","42"]',2,'10% of 240 is 24, and 5% is 12. Together, 15% is 36.'),
('daily-2','daily',2,'What number comes next: 2, 6, 12, 20, 30, …?','["36","40","42","44"]',2,'The differences grow by two: +4, +6, +8, +10, then +12. So the next value is 42.'),
('daily-3','daily',3,'A program repeats a block while a condition is true. Which idea is this?','["Iteration","Declaration","Compilation","Assignment"]',0,'Iteration means repeating a block of work, commonly with a loop.'),
('daily-4','daily',4,'How many bits are in one byte in the usual modern definition?','["4","8","16","32"]',1,'A byte is made up of 8 bits.'),
('daily-5','daily',5,'What is the average of 6, 8, and 10?','["7","8","9","24"]',1,'The sum is 24; divide by 3 values to get an average of 8.'),
('numerical-1','numerical',1,'What is 15% of 240?','["24","30","36","42"]',2,'10% is 24 and 5% is 12; together they make 36.'),
('numerical-2','numerical',2,'A ratio is 3:5 and the total is 64. What is the smaller part?','["18","21","24","32"]',2,'There are 8 equal parts. 64 divided by 8 is 8; the smaller part is 3 × 8 = 24.'),
('numerical-3','numerical',3,'What number comes next: 2, 6, 12, 20, 30, …?','["36","40","42","44"]',2,'The differences are +4, +6, +8, +10. Add +12 to get 42.'),
('numerical-4','numerical',4,'The mean of 4, 7, and one other number is 8. What is the third number?','["9","11","13","15"]',2,'A mean of 8 across 3 values needs a total of 24. 24 − 4 − 7 = 13.'),
('logic-1','logic',1,'Which number continues the pattern: 1, 4, 9, 16, …?','["20","24","25","36"]',2,'These are square numbers: 1², 2², 3², 4². The next is 5² = 25.'),
('logic-2','logic',2,'All zips are folders. Some folders are shared. Which statement must be true?','["All zips are shared","Some zips are shared","All zips are folders","No folders are zips"]',2,'The first sentence directly guarantees that every zip belongs to the folder group.'),
('logic-3','logic',3,'If A comes before B, and B comes before C, which must come last?','["A","B","C","There is not enough information"]',2,'The two ordering relationships place C after both A and B.'),
('logic-4','logic',4,'Which item is the odd one out?','["Triangle","Square","Circle","Cube"]',3,'A cube is three-dimensional; the other shapes are two-dimensional.'),
('computing-1','computing',1,'Which part of a computer carries out most instructions?','["CPU","Monitor","Keyboard","Speaker"]',0,'The central processing unit (CPU) executes program instructions.'),
('computing-2','computing',2,'What is the smallest unit of digital information?','["Byte","Bit","Pixel","Word"]',1,'A bit can represent one of two values, often written as 0 or 1.'),
('computing-3','computing',3,'Which memory is typically cleared when a computer loses power?','["RAM","SSD","Flash drive","Hard disk"]',0,'RAM is volatile working memory; it does not retain its contents without power.'),
('computing-4','computing',4,'What does a compiler primarily do?','["Draws the user interface","Translates source code","Stores a password","Connects a keyboard"]',1,'A compiler translates source code into another form, commonly machine code or an intermediate form.'),
('code-1','code',1,'In C, what value is printed by printf with the expression 3 + 4?','["34","7","3 + 4","A compile error"]',1,'The expression 3 + 4 is evaluated first, so the integer printed is 7.'),
('code-2','code',2,'In C++, what does values[0] refer to in a non-empty vector?','["Its first element","Its last element","Its number of elements","The vector type"]',0,'Sequence indexing begins at zero, so index 0 refers to the first element.'),
('code-3','code',3,'How many times does a loop body run when i starts at 0 and continues while i < 3?','["2","3","4","It never runs"]',1,'The values 0, 1, and 2 satisfy i < 3. At 3 the condition is false.'),
('code-4','code',4,'What is x after int x = 5; x += 2;?','["2","5","7","10"]',2,'The += operator adds 2 to the current value, so x becomes 7.');
